      background: rgba(15, 23, 42, 0.72);
      color: var(--accent);
      font-size: 0.92rem;
      letter-spacing: 0.02em;
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(2.2rem, 4vw, 3.4rem);
      line-height: 1.1;
    }

    .intro {
      max-width: 62ch;
      margin: 0;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .faq-list {
      display: grid;
      gap: 1rem;
    }

    .example {
      border: 1px solid var(--border);
      border-radius: var(--radius);
      background: linear-gradient(180deg, rgba(15, 23, 42, 0.95), rgba(9, 14, 29, 0.94));
      box-shadow: var(--shadow);
      overflow: clip;
    }

